<?php require_once '../config.php';$uid=guard();$m=$_SERVER['REQUEST_METHOD'];
if($m==='GET'){$s=db()->prepare('SELECT id,title,description,due_date dueDate,priority,category,completed done,created_at createdAt FROM tasks WHERE user_id=? ORDER BY created_at DESC');$s->execute([$uid]);$a=$s->fetchAll();foreach($a as &$x)$x['done']=(bool)$x['done'];out(['ok'=>true,'tasks'=>$a,'csrf'=>csrf()]);}
check();$d=body();
if($m==='POST'){$s=db()->prepare('INSERT INTO tasks(user_id,title,description,due_date,priority,category,completed) VALUES(?,?,?,?,?,?,?)');$s->execute([$uid,trim($d['title']),trim($d['description']??'')?:null,$d['dueDate']?:null,$d['priority']??'media',trim($d['category']??'')?:null,0]);out(['ok'=>true],201);}
$id=(int)($d['id']??0);
if($m==='PUT'){$s=db()->prepare('UPDATE tasks SET title=?,description=?,due_date=?,priority=?,category=?,completed=? WHERE id=? AND user_id=?');$s->execute([trim($d['title']),trim($d['description']??'')?:null,$d['dueDate']?:null,$d['priority']??'media',trim($d['category']??'')?:null,!empty($d['done'])?1:0,$id,$uid]);out(['ok'=>true]);}
if($m==='DELETE'){$s=db()->prepare('DELETE FROM tasks WHERE id=? AND user_id=?');$s->execute([$id,$uid]);out(['ok'=>true]);}out(['ok'=>false,'error'=>'Método inválido'],405);?>